mapper.select:
SELECT n.id, n.title, n.content, n.photo_url, n.origin, n.source_url, n.publish_time, n.read_count, n.like_count, n.comment_count, n.ai_summary, n.ai_keywords, n.ai_status, n.ai_model, n.category_id, c.name AS category_name
, (SELECT COUNT(1) FROM user_action ua WHERE ua.user_id = #{userId} AND ua.target_type = 2 AND ua.target_id = n.id) AS is_like , (SELECT COUNT(1) FROM user_action ua WHERE ua.user_id = #{userId} AND ua.target_type = 1 AND ua.target_id = n.id) AS is_favorite
FROM news n LEFT JOIN news_category c ON c.id = n.category_id WHERE n.id = #{id}
